css:
.cmd-palette-scope .cmd-palette-container {
  width: 100%;
  max-width: 480px;
}
.cmd-palette-scope .cmd-palette-card {
  background: #ffffff;
  border-radius: 12px;
  box-shadow:
    0 20px 40px -10px rgba(0, 0, 0, 0.08),
    0 8px 20px -4px rgba(0, 0, 0, 0.04);
  overflow: hidden;
  border: 1px solid rgba(0, 0, 0, 0.04);
}
.cmd-palette-scope .cmd-palette-search {
  display: flex;
  align-items: center;
  padding: 10px 14px;
  border-bottom: 1px solid #f3f4f6;
  gap: 10px;
}
.cmd-palette-scope .cmd-palette-search-icon {
  color: #9ca3af;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.cmd-palette-scope .cmd-palette-search-icon svg {
  width: 16px;
  height: 16px;
  stroke-width: 2;
}
.cmd-palette-scope .cmd-palette-input {
  flex: 1;
  border: none;
  outline: none;
  font-size: 13px;
  color: #111827;
  background: transparent;
  font-family: "Inter", sans-serif;
  font-weight: 400;
  letter-spacing: -0.01em;
  margin: 0;
  padding: 0;
}
.cmd-palette-scope .cmd-palette-input::placeholder {
  color: #9ca3af;
  font-weight: 400;
}
.cmd-palette-scope .cmd-palette-hint {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 5px;
  padding: 3px 6px;
  font-size: 11px;
  color: #6b7280;
  font-family: "Inter", monospace;
  font-weight: 500;
  letter-spacing: 0.02em;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.02);
}
.cmd-palette-scope .cmd-palette-content {
  padding: 4px 0;
}
.cmd-palette-scope .cmd-palette-section {
  padding: 4px 0;
}
.cmd-palette-scope .cmd-palette-section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 12px;
  margin-bottom: 4px;
  margin-top: 2px;
}
.cmd-palette-scope .cmd-palette-section-title {
  font-size: 11px;
  color: #6b7280;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.cmd-palette-scope .cmd-palette-clear {
  background: none;
  border: none;
  color: #6b7280;
  font-size: 11px;
  cursor: pointer;
  font-weight: 500;
  font-family: "Inter", sans-serif;
  padding: 2px 4px;
  border-radius: 4px;
  transition: all 0.15s ease;
}
.cmd-palette-scope .cmd-palette-clear:hover {
  color: #111827;
  background: #f9fafb;
}
.cmd-palette-scope .cmd-palette-item {
  display: flex;
  align-items: center;
  padding: 6px 8px;
  margin: 0 6px;
  border-radius: 6px;
  cursor: pointer;
  gap: 10px;
  position: relative;
  transition: background-color 0.15s ease;
}
.cmd-palette-scope .cmd-palette-item:hover {
  background-color: #f9fafb;
}
.cmd-palette-scope .cmd-palette-item-selected {
  background-color: #f3f4f6;
}
.cmd-palette-scope .cmd-palette-icon {
  color: #6b7280;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
}
.cmd-palette-scope .cmd-palette-icon svg {
  width: 14px;
  height: 14px;
  stroke-width: 1.75;
}
.cmd-palette-scope .cmd-palette-icon-hash svg {
  stroke-width: 2;
}
.cmd-palette-scope .cmd-palette-icon-slack svg {
  width: 16px;
  height: 16px;
  stroke-width: 0;
}
.cmd-palette-scope .cmd-palette-text {
  flex: 1;
  font-size: 12px;
  color: #111827;
  font-weight: 450;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  letter-spacing: -0.01em;
}
.cmd-palette-scope .cmd-palette-meta {
  display: flex;
  align-items: center;
  gap: 8px;
}
.cmd-palette-scope .cmd-palette-avatar-group {
  display: flex;
  align-items: center;
  direction: ltr;
}
.cmd-palette-scope .cmd-palette-avatar {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid #ffffff;
  margin-left: -6px;
  position: relative;
  overflow: hidden;
}
.cmd-palette-scope .cmd-palette-avatar:first-child {
  margin-left: 0;
}
.cmd-palette-scope .cmd-palette-avatar-img {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}
.cmd-palette-scope .cmd-palette-avatar-img-2 {
  background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
}
.cmd-palette-scope .cmd-palette-avatar-img-3 {
  background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%);
}
.cmd-palette-scope .cmd-palette-avatar-img-4 {
  background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%);
}
.cmd-palette-scope .cmd-palette-avatar-img-5 {
  background: linear-gradient(135deg, #fa709a 0%, #fee140 100%);
}
.cmd-palette-scope .cmd-palette-avatar-img-6 {
  background: linear-gradient(135deg, #30cfd0 0%, #330867 100%);
}
.cmd-palette-scope .cmd-palette-avatar-badge {
  background-color: #18181b;
  color: #ffffff;
  font-size: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.cmd-palette-scope .cmd-palette-jump {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 4px;
  padding: 2px 8px;
  font-size: 11px;
  color: #6b7280;
  cursor: pointer;
  font-weight: 500;
  font-family: "Inter", sans-serif;
  transition: all 0.15s ease;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.02);
}
.cmd-palette-scope .cmd-palette-jump:hover {
  border-color: #d1d5db;
  background-color: #f9fafb;
  color: #111827;
}
.cmd-palette-scope .cmd-palette-slack-meta {
  display: flex;
  align-items: center;
  gap: 6px;
}
.cmd-palette-scope .cmd-palette-uber {
  font-size: 11px;
  color: #6b7280;
  background: #ffffff;
  padding: 1px 6px;
  border-radius: 4px;
  border: 1px solid #e5e7eb;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.cmd-palette-scope .cmd-palette-badge {
  background-color: #eef2ff;
  color: #4f46e5;
  font-size: 11px;
  font-weight: 600;
  padding: 0px 7px;
  border-radius: 10px;
  min-width: 18px;
  text-align: center;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}
.cmd-palette-scope .cmd-palette-separator {
  height: 1px;
  background-color: #f3f4f6;
  margin: 4px 12px;
}
.cmd-palette-scope .cmd-palette-footer {
  display: flex;
  align-items: center;
  padding: 10px 12px;
  border-top: 1px solid #f3f4f6;
  gap: 16px;
  background: #ffffff;
}
.cmd-palette-scope .cmd-palette-shortcut {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  color: #9ca3af;
  font-weight: 500;
}
.cmd-palette-scope .cmd-palette-key {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 4px;
  padding: 1px 5px;
  font-size: 10px;
  color: #6b7280;
  font-family: "Inter", monospace;
  font-weight: 600;
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.04);
  min-width: 18px;
  text-align: center;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 18px;
}
